nodeTypes.inlineCode:
const float error = Setpoint - Measurement;
integral += error;
float raw_output = Kp * error + Ki * integral;
if (raw_output > OutputMax) raw_output = OutputMax;
if (raw_output < OutputMin) raw_output = OutputMin;
Output = raw_output;

const float counts_per_rad = CountsPerRev / 6.28318530718f;
const float dt_s = SampleTime;

Theta = static_cast<float>(RawCounts) / counts_per_rad;

const float delta = static_cast<float>(RawCounts) - prev_counts;
Omega = rte::RadiansPerSecond(delta / (counts_per_rad * dt_s));
prev_counts = static_cast<float>(RawCounts);

// ADC1 injected: U signal CH4 (rank 1), V signal CH3 (rank 2)
// ADC2 injected: U reference CH8 (rank 1), V reference CH7 (rank 2)
// Triggered by TIM1 TRGO at PWM bottom; read in ADC ISR.
static constexpr float ADC_VREF = 3.3f;
static constexpr float DIVIDER = 2.0f / 3.0f;
static constexpr float SENSITIVITY_VA = 1.042e-3f;  // LA37S600
static constexpr float COUNTS_FULL = 65535.0f;

const float scale = (ADC_VREF / COUNTS_FULL) / (DIVIDER * SENSITIVITY_VA);

const uint32_t raw_u_sig = platform_adc_get_injected_u_sig();
const uint32_t raw_v_sig = platform_adc_get_injected_v_sig();
const uint32_t raw_u_ref = platform_adc_get_injected_u_ref();
const uint32_t raw_v_ref = platform_adc_get_injected_v_ref();

const rte::Current iu_raw = rte::Amperes((static_cast<float>(raw_u_sig) - static_cast<float>(raw_u_ref)) * scale);
const rte::Current iv_raw = rte::Amperes((static_cast<float>(raw_v_sig) - static_cast<float>(raw_v_ref)) * scale);

// Subtract calibrated zero-current offsets from the base image's startup calibration.
const rte::Current calibrated_offset_u = rte::Amperes(platform_adc_get_offset_u_a());
const rte::Current calibrated_offset_v = rte::Amperes(platform_adc_get_offset_v_a());
const rte::Current iu_a = iu_raw - calibrated_offset_u;
const rte::Current iv_a = iv_raw - calibrated_offset_v;

// W is computed from the two measured phases (three-wire balanced load).
const rte::Current iw_a = rte::Amperes(-(iu_a.in(au::amperes) + iv_a.in(au::amperes)));

/* The phase-current sensors on this hardware are wired with inverted polarity
 * relative to the FOC convention.  Negate all three so downstream transforms
 * see the correct sign (matches base-image FocControlManager). */
I_A = -iu_a;
I_B = -iv_a;
I_C = -iw_a;

V_A = V_Alpha;
V_B = -0.5f * V_Alpha + 0.86602540378f * V_Beta;
V_C = -0.5f * V_Alpha - 0.86602540378f * V_Beta;

const float cos_theta = cosf(Theta);
const float sin_theta = sinf(Theta);
V_Alpha = V_D * cos_theta - V_Q * sin_theta;
V_Beta = V_D * sin_theta + V_Q * cos_theta;

const float cos_theta = cosf(Theta);
const float sin_theta = sinf(Theta);
I_D = I_Alpha * cos_theta + I_Beta * sin_theta;
I_Q = -I_Alpha * sin_theta + I_Beta * cos_theta;

/* Clamp the alpha/beta voltage vector to the linear SVM limit.
 * The maximum line-to-neutral voltage magnitude for linear modulation is
 * Vdc / sqrt(3).  Use a small margin to stay away from the overmodulation
 * boundary. */
const float sqrt3 = 1.7320508075688772f;
const float v_max_linear = (V_Dc.in(au::volts) / sqrt3) * 0.95f;
float valpha = V_Alpha.in(au::volts);
float vbeta  = V_Beta.in(au::volts);
const float v_albe_sq = valpha * valpha + vbeta * vbeta;
if (v_albe_sq > v_max_linear * v_max_linear && v_albe_sq > 1e-12f) {
    const float scale = v_max_linear / sqrtf(v_albe_sq);
    valpha *= scale;
    vbeta  *= scale;
}

/* Inverse Clarke: alpha/beta -> A/B/C. */
const float v_a = valpha / V_Dc.in(au::volts);
const float v_b = (-0.5f * valpha + 0.86602540378f * vbeta) / V_Dc.in(au::volts);
const float v_c = (-0.5f * valpha - 0.86602540378f * vbeta) / V_Dc.in(au::volts);

float v_min = v_a;
if (v_b < v_min) v_min = v_b;
if (v_c < v_min) v_min = v_c;

float v_max = v_a;
if (v_b > v_max) v_max = v_b;
if (v_c > v_max) v_max = v_c;

const float v_offset = 0.5f * (v_min + v_max);

/* Convert to percent duty and clamp.  Linear SVM stays roughly in
 * [21%, 79%]; clamping to [0,100] only catches numerical edge cases. */
float duty_a_pct = 50.0f + 50.0f * (v_a - v_offset);
float duty_b_pct = 50.0f + 50.0f * (v_b - v_offset);
float duty_c_pct = 50.0f + 50.0f * (v_c - v_offset);

if (duty_a_pct < 0.0f) duty_a_pct = 0.0f; else if (duty_a_pct > 100.0f) duty_a_pct = 100.0f;
if (duty_b_pct < 0.0f) duty_b_pct = 0.0f; else if (duty_b_pct > 100.0f) duty_b_pct = 100.0f;
if (duty_c_pct < 0.0f) duty_c_pct = 0.0f; else if (duty_c_pct > 100.0f) duty_c_pct = 100.0f;

Duty_A = duty_a_pct;
Duty_B = duty_b_pct;
Duty_C = duty_c_pct;

const float error = (Setpoint - Measurement).in(au::amperes);
Integral += error * Dt;

float raw_output = Kp * error + Ki * Integral;

/* Dynamic voltage limit derived from DC-link voltage, matching the base
 * image's VectorPIController convention: max = Vdc * 0.5 * MaxModulation. */
const float vdc = platform_get_dc_link_voltage();
const float dynamic_max = vdc * 0.5f * 0.9f;
const float max_limit = (dynamic_max < OutputMax) ? dynamic_max : OutputMax;
const float min_limit = (-dynamic_max > OutputMin) ? -dynamic_max : OutputMin;

float limited_output = raw_output;
if (limited_output > max_limit) limited_output = max_limit;
if (limited_output < min_limit) limited_output = min_limit;

/* Back-calculation anti-windup (matches base-image VectorPIController). */
if (Ki > 0.0001f && Kp > 0.0001f) {
    const float excess = raw_output - limited_output;
    Integral -= excess * Dt / (Kp * Ki);
}

Output = rte::Volts(limited_output);

float iu_f = 0.0f;
float iv_f = 0.0f;
float iw_f = 0.0f;
if (platform_get_phase_currents(&iu_f, &iv_f, &iw_f)) {
    I_U = rte::Amperes(iu_f);
    I_V = rte::Amperes(iv_f);
    I_W = rte::Amperes(iw_f);
}

platform_telemetry_log_f32("cg_iu_a", I_A.in(au::amperes));
platform_telemetry_log_f32("cg_iv_a", I_B.in(au::amperes));
platform_telemetry_log_f32("cg_iw_a", I_C.in(au::amperes));

/* Wrap the mechanical encoder angle to [0, 2*pi). */
const float two_pi = 6.28318530718f;
float theta = fmodf(ThetaMech, two_pi);
if (theta < 0.0f) theta += two_pi;

/* Electrical angle = offset (elec deg) + sign * encoder_angle * (Poles / 2).
 * Matches the base-image FocController convention. */
constexpr float DEG_TO_RAD = 0.01745329251f;
float elec = OffsetDeg * DEG_TO_RAD + EncoderSign * theta * Poles * 0.5f;

/* Wrap the electrical angle to [0, 2*pi). */
elec = fmodf(elec, two_pi);
if (elec < 0.0f) elec += two_pi;

ThetaElec = elec;

Angle += RateRadPerS * Dt;
if (Angle >= 6.28318530718f) Angle -= 6.28318530718f;
ThetaElec = Angle;
